[r'v_{t+1}=\beta v_t+I',r'v^*=\beta v^*+I',r'v^*=\frac{I}{1-\beta}'],
[num('With I = 0.3 and β = 0.5, what is the equilibrium without resets?',.6,'0.3 / (1 − 0.5) = 0.6.',requires=['leak']),single('If the level is above equilibrium, what happens without resets?',['It tends downward','It grows forever'],0,'Leak exceeds the constant input above equilibrium.')],
